(() => {
  const KEY='realEduSupportPreviewV1', OWN='realEduSupportConversation';
  const admin=!!document.querySelector('#support-admin');
  let selected='',filter='전체',opened=false;
  const read=()=>{try{const d=JSON.parse(localStorage.getItem(KEY)||'[]');return Array.isArray(d)?d:[];}catch{return [];}};
  const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  function save(data){try{localStorage.setItem(KEY,JSON.stringify(data));return true;}catch{document.querySelector('#support-feedback').textContent='브라우저 저장 공간을 사용할 수 없습니다.';return false;}}
  if(!admin){try{selected=localStorage.getItem(OWN)||'';}catch{}}
  const root=document.createElement('section');root.className=admin?'support-workspace':'support-widget';
  root.innerHTML=admin?'<div class="support-list"><h2>상담함</h2><select id="support-filter" aria-label="상담 상태 필터"><option>전체</option><option>미읽음</option><option>접수</option><option>처리 중</option><option>완료</option></select><div id="support-threads"></div></div><div class="support-conversation"></div>':'<button class="support-launch" aria-label="문의 상담 열기" aria-expanded="false" aria-controls="support-panel">✦ 문의하기 <span id="support-badge"></span></button><div id="support-panel" hidden role="region" aria-label="REAL-Edu 문의 상담"><div class="support-head"><div><b>REAL-Edu</b><small>배움의 시작을 함께할게요</small></div><button id="support-close" aria-label="상담 닫기">×</button></div><div class="support-conversation"></div></div>';
  (admin?document.querySelector('#support-admin'):document.body).append(root);
  const conv=root.querySelector('.support-conversation');
  conv.innerHTML='<div class="support-notice">UI 체험 · 이 브라우저에만 저장됩니다. 실제 상담원에게 전달되지 않으니 개인정보는 입력하지 마세요.</div><div id="support-context"></div><div id="support-messages" role="log" aria-label="상담 대화"></div><form id="support-form"><label class="support-topic">문의 유형<select name="topic"><option>수강 문의</option><option>결제·환불</option><option>기업 교육</option><option>기타</option></select></label><label class="support-compose">'+(admin?'상담 답변':'문의 내용')+'<textarea name="message" rows="3" maxlength="2000" required placeholder="'+(admin?'답변을 작성해 주세요.':'궁금한 내용을 남겨주세요.')+'"></textarea></label><button type="submit">'+(admin?'답변 보내기 · 시안':'문의 남기기 · 시안')+'</button></form><p id="support-feedback" role="status"></p>';
  const form=root.querySelector('form'),messages=root.querySelector('#support-messages'),context=root.querySelector('#support-context');
  function markRead(){const data=read(),t=data.find(t=>t.id===selected);if(t&&t[admin?'adminUnread':'visitorUnread']){t[admin?'adminUnread':'visitorUnread']=false;save(data);}}
  function render(){const data=read(),t=data.find(t=>t.id===selected);
    if(admin){root.querySelector('#support-threads').innerHTML=data.filter(t=>filter==='전체'||(filter==='미읽음'?t.adminUnread:t.status===filter)).map(t=>'<button class="support-thread '+(t.id===selected?'selected':'')+'" data-thread="'+esc(t.id)+'"><b>'+esc(t.topic)+(t.adminUnread?' · ●':'')+'</b><small>'+esc(t.status)+' · '+new Date(t.at).toLocaleDateString('ko-KR')+'</small><span>'+esc(t.messages.at(-1)?.text)+'</span></button>').join('')||'<p class="support-empty">아직 문의가 없습니다.<br>홈페이지의 문의창에서 테스트 내용을 남겨보세요.</p>';form.hidden=!t;form.querySelector('.support-topic').hidden=true;context.innerHTML=t?'<div class="support-status"><b>'+esc(t.topic)+'</b><label>처리 상태 <select id="support-state">'+['접수','처리 중','완료'].map(s=>'<option '+(s===t.status?'selected':'')+'>'+s+'</option>').join('')+'</select></label></div>':'<p class="support-empty">확인할 상담을 선택해 주세요.</p>';}
    else {form.querySelector('.support-topic').hidden=!!t;context.innerHTML=t?'<div class="support-status"><span>'+esc(t.topic)+' · '+esc(t.status)+'</span><button type="button" id="support-new">새 문의</button></div>':'';root.querySelector('#support-badge').textContent=t?.visitorUnread?'●':'';}
    messages.innerHTML=t?t.messages.map(m=>'<div class="support-message '+(m.role==='admin'?'staff':'visitor')+'"><small>'+ (m.role==='admin'?'REAL-Edu 운영자':'방문자')+'</small><p>'+esc(m.text)+'</p><time>'+new Date(m.at).toLocaleTimeString('ko-KR',{hour:'2-digit',minute:'2-digit'})+'</time></div>').join(''):(admin?'':'<div class="support-message staff"><small>REAL-Edu</small><p>안녕하세요! 어떤 배움이 궁금하세요?<br>강좌부터 팀 워크숍까지 편하게 남겨주세요.</p></div>');messages.scrollTop=messages.scrollHeight;
  }
  form.addEventListener('submit',e=>{e.preventDefault();const input=form.elements.message,text=input.value.trim();if(!text)return;const data=read();let t=data.find(t=>t.id===selected);if(!t){if(admin)return;t={id:crypto.randomUUID(),topic:form.elements.topic.value,status:'접수',at:Date.now(),messages:[]};data.unshift(t);}t.messages.push({role:admin?'admin':'visitor',text,at:Date.now()});t[admin?'visitorUnread':'adminUnread']=true;if(admin&&t.status==='접수')t.status='처리 중';if(!admin&&t.status==='완료')t.status='접수';if(save(data)){selected=t.id;if(!admin){try{localStorage.setItem(OWN,selected);}catch{}}input.value='';render();root.querySelector('#support-feedback').textContent='이 브라우저에 저장했습니다.';}});
  root.addEventListener('click',e=>{const thread=e.target.closest('[data-thread]');if(thread){selected=thread.dataset.thread;markRead();render();}if(e.target.closest('#support-new')){selected='';try{localStorage.removeItem(OWN);}catch{}render();}if(e.target.closest('.support-launch')||e.target.closest('#support-close')){opened=!opened;root.querySelector('#support-panel').hidden=!opened;root.querySelector('.support-launch').setAttribute('aria-expanded',String(opened));if(opened){markRead();render();form.elements.message.focus();}else root.querySelector('.support-launch').focus();}});
  root.addEventListener('change',e=>{if(e.target.id==='support-filter'){filter=e.target.value;render();}if(e.target.id==='support-state'){const d=read(),t=d.find(t=>t.id===selected);if(t){t.status=e.target.value;save(d);render();}}});
  root.addEventListener('keydown',e=>{if(e.key==='Escape'&&!admin&&opened){root.querySelector('#support-close').click();}});
  window.addEventListener('storage',e=>{if(e.key===KEY){if(admin||opened)markRead();render();}});render();
})();
